def at(s): return datetime.fromisoformat(s.replace("Z","+00:00")).astimezone(timezone.utc)
def row(output,pair): return next(x for x in output["pairs"] if x["pair"]==pair)

class EarlyMoveTests(unittest.TestCase):
    def test_early_watch_before_fifteen_minute_close(self):
        out=run(FIXTURE,at=at("2026-10-12T23:06:00Z"),strict_freshness=False)
        a=row(out,"AUDJPY")
        self.assertEqual(a["direction"],"SELL")
        self.assertEqual(a["stage"],"PRE_BREAKOUT_WATCH")
        self.assertAlmostEqual(a["latest_closed_m5"],110.327,places=3)
        self.assertAlmostEqual(a["range_low"],110.341,places=3)
        self.assertFalse(a["execution_allowed"])
        self.assertTrue(any(x["pair"]=="AUDJPY" for x in out["top_five_early_priority"]))

    def test_fifteen_minute_confirms_without_waiting_for_hour(self):
        out=run(FIXTURE,at=at("2026-10-12T23:16:00Z"),strict_freshness=False)
        a=row(out,"AUDJPY")
        self.assertEqual(a["direction"],"SELL")
        self.assertEqual(a["stage"],"BREAKOUT_CONFIRMING")
        self.assertAlmostEqual(a["latest_closed_m15"],110.315,places=3)
        self.assertFalse(a["execution_allowed"])
        self.assertGreaterEqual(out["jpy_cluster"]["jpy_strength_crosses"],3)

    def test_four_jpy_crosses_rotate_before_hourly_confirmation(self):
        early=run(FIXTURE,at=at("2026-10-12T23:06:00Z"),strict_freshness=False)
        self.assertEqual(early["jpy_cluster"]["status"],"BROAD_JPY_STRENGTH")
        self.assertEqual(early["jpy_cluster"]["jpy_strength_crosses"],4)
        confirming=run(FIXTURE,at=at("2026-10-12T23:16:00Z"),strict_freshness=False)
        self.assertEqual(confirming["jpy_cluster"]["jpy_strength_crosses"],4)
        for pair in ("AUDJPY","EURJPY","NZDJPY","USDJPY"):
            self.assertEqual(row(confirming,pair)["direction"],"SELL")
        top={x["pair"] for x in confirming["top_five_early_priority"]}
        self.assertTrue({"AUDJPY","NZDJPY"}.issubset(top))

    def test_future_candles_cannot_change_early_decision(self):
        cutoff=at("2026-10-12T23:06:00Z")
        before=run(FIXTURE,at=cutoff,strict_freshness=False)
        changed=copy.deepcopy(FIXTURE)
        for tf in ("M5","M15"):
            bars=changed["pairs"]["AUDJPY"]["tf"][tf]
            for i,t in enumerate(bars["t"]):
                if t-10800 > cutoff.timestamp():
                    bars["o"][i]=200.;bars["h"][i]=200.2
                    bars["l"][i]=199.8;bars["c"][i]=200.
        after=run(changed,at=cutoff,strict_freshness=False)
        a,b=row(before,"AUDJPY"),row(after,"AUDJPY")
        self.assertEqual((a["direction"],a["stage"],a["range_low"],a["latest_closed_m5"]),
                         (b["direction"],b["stage"],b["range_low"],b["latest_closed_m5"]))

    def test_signal_episode_persists_and_never_approves_order(self):
        t1=at("2026-10-12T23:06:00Z")
        t2=at("2026-10-12T23:16:00Z")
        first=run(FIXTURE,at=t1,strict_freshness=False)
        second=run(FIXTURE,at=t2,previous=first,strict_freshness=False)
        start=next(x for x in first["active_episodes"] if x["pair"]=="AUDJPY")
        later=next(x for x in second["active_episodes"] if x["pair"]=="AUDJPY")
        self.assertEqual(start["first_observed_at_utc"],later["first_observed_at_utc"])
        self.assertEqual(later["stage"],"BREAKOUT_CONFIRMING")
        self.assertFalse(later["execution_allowed"])

    def test_quiet_hours_suppresses_alerts(self):
        out=run(FIXTURE,at=at("2026-10-16T18:30:00Z"),strict_freshness=False)
        self.assertTrue(out["quiet_hours"])
        self.assertEqual(out["top_five_early_priority"],[])

    def test_broken_server_clock_cannot_pass_fresh_gate(self):
        bad=copy.deepcopy(FIXTURE)
        bad["source_timestamp"]+=1800
        out=run(bad,at=at("2026-10-12T23:06:00Z"),strict_freshness=False)
        self.assertEqual(out["status"],"MISSING_OR_STALE_SOURCE")

if __name__=="__main__":unittest.main()
